import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

const validatorOptions = {strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0];
const schemaValidator = new Ajv(validatorOptions);

function schemaRejection(errors: unknown[]): ToolResponse {
  const error = errors[0];
  const keyword = errorProperty(error, 'keyword');
  const params = errorProperty(error, 'params');
  const missingProperty = errorProperty(params, 'missingProperty');
  const expectedType = errorProperty(params, 'type');
  const instancePath = errorProperty(error, 'instancePath');
  const propertyPath =
    typeof missingProperty === 'string'
      ? `${typeof instancePath === 'string' ? instancePath : ''}/${missingProperty.replace(/~/g, '~0').replace(/\//g, '~1')}`
      : (typeof instancePath === 'string' && instancePath) || 'input';
  const issue =
    keyword === 'required'
      ? 'is required'
      : keyword === 'type' && typeof expectedType === 'string'
        ? `must be a ${expectedType}`
        : `must satisfy ${String(keyword)}`;
  return {result: `Invalid input at ${propertyPath}: ${issue}.`};
}

function errorProperty(error: unknown, property: string): unknown {
  if (typeof error !== 'object' || error === null || !(property in error)) return undefined;
  return (error as Record<string, unknown>)[property];
}

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const staticValidator =
      typeof definition === 'function' ? undefined : this.compileSchema(resolved.inputSchema, resolved.name);
    this.tools.set(resolved.name, {definitionSource: definition, execute, staticValidator});
  }

  private compileSchema(schema: object, name: string): ValidateFunction {
    try {
      return schemaValidator.compile(schema);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool ${name}: ${message}`, {cause: error});
    }
  }

  private dynamicValidator(schema: object, name: string): ValidateFunction {
    const cached = this.dynamicValidators.get(schema);
    if (cached) return cached;
    const validator = this.compileSchema(schema, name);
    this.dynamicValidators.set(schema, validator);
    return validator;
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Returns schema rejections as tool results; only an unknown tool name throws (see specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = tool.staticValidator ?? this.dynamicValidator(definition.inputSchema, definition.name);
    if (!validate(input)) {
      return schemaRejection(validate.errors ?? []);
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import Ajv from 'ajv';
import {jest} from '@jest/globals';
import type {ToolDefinition} from '../../types/ai.js';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  it('returns a required-property rejection without running the tool', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    const weatherDefinition = {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    } satisfies ToolDefinition;
    registry.register(weatherDefinition, async () => ((executorCalls += 1), 'sunny'));

    const response = await registry.execute('get_weather', {});

    expect({executorCalls, rejectionNamesRequiredLocation: /location.*required/i.test(response.result)}).toEqual({
      executorCalls: 0,
      rejectionNamesRequiredLocation: true,
    });
  });

  it('names the full path of a missing nested required property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'nested_lookup',
        description: 'Look up a nested value',
        inputSchema: {
          type: 'object',
          properties: {
            user: {
              type: 'object',
              properties: {location: {type: 'string'}},
              required: ['location'],
            },
          },
          required: ['user'],
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('nested_lookup', {user: {}});

    expect(response.result).toContain('/user/location');
  });

  it('describes the expected type for an invalid field without echoing its value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup_record',
        description: 'Look up a record',
        inputSchema: {
          type: 'object',
          properties: {identifier: {type: 'string'}},
          required: ['identifier'],
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('lookup_record', {identifier: 912345});

    expect({
      namesExpectedType: response.result.includes('string'),
      leaksValue: response.result.includes('912345'),
    }).toEqual({
      namesExpectedType: true,
      leaksValue: false,
    });
  });

  it('compiles a static schema only once across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'cached_tool',
        description: 'A tool with a cached schema',
        inputSchema: {type: 'object', properties: {value: {type: 'string'}}},
      },
      async () => 'ok'
    );

    for (let attempt = 0; attempt < 10; attempt += 1) {
      await registry.execute('cached_tool', {value: 'valid'});
    }

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required, including its full nested path, and never invokes the executor ([validated by: returns a required-property rejection without running the tool](../../src/orchestration/tools/registry.test.ts#L7), [validated by: names the full path of a missing nested required property](../../src/orchestration/tools/registry.test.ts#L25), [validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: describes the expected type for an invalid field without echoing its value](../../src/orchestration/tools/registry.test.ts#L51), [validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: compiles a static schema only once across repeated executions](../../src/orchestration/tools/registry.test.ts#L77)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules.

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).

import {ToolRegistry} from './registry.js';
import {createChatOrchestrator} from '../chatOrchestrator.js';
import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import type {AIProvider, MessageChunk, SendMessageParams, ToolResultMessage} from '../../types/ai.js';
import type {ChatSession} from '../../types/session.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

describe('ToolRegistry inputSchema validation acceptance', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      mentionsRequiredField: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      mentionsRequiredField: true,
    });
  });

  it('rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'ssn_lookup',
        description: 'Look up record by identifier',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
          required: ['ssn'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('ssn_lookup', {ssn: 123456789});

    expect({
      executorCalls,
      mentionsField: response.result.includes('ssn'),
      mentionsExpectedType: response.result.includes('string'),
      leaksValueInResult: response.result.includes('123456789'),
      leaksValueInLogs: recordedLogs.some(line => line.includes('123456789')),
    }).toEqual({
      executorCalls: 0,
      mentionsField: true,
      mentionsExpectedType: true,
      leaksValueInResult: false,
      leaksValueInLogs: false,
    });
  });

  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });

  it('returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round', async () => {
    const registry = new ToolRegistry();
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      () => ({
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      }),
      async input => {
        executorInputs.push(input);
        return `22C in ${String(input.location)}`;
      }
    );

    let firstRoundToolResult = '';
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        round += 1;
        if (round === 1) {
          yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'get_weather', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        if (round === 2) {
          const lastMessage = params.messages[params.messages.length - 1] as ToolResultMessage;
          firstRoundToolResult = lastMessage.content[0]?.content ?? '';
          yield {
            type: 'tool_use',
            toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Paris'}},
          };
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        yield {type: 'text', text: '22C in Paris'};
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(
      provider,
      new PromptBuilder({identity: 'You are a test assistant.'}),
      registry
    );
    const session: ChatSession = {
      sessionId: 's-retry',
      userId: 'u1',
      entries: [{role: 'user', content: 'Weather in Paris?', timestamp: SENT_AT}],
    };

    const reply = await orchestrator.processMessage(session);

    expect({
      reply,
      executorInputs,
      firstAttemptRejectedForLocation:
        firstRoundToolResult.includes('location') && /required/i.test(firstRoundToolResult),
    }).toEqual({
      reply: '22C in Paris',
      executorInputs: [{location: 'Paris'}],
      firstAttemptRejectedForLocation: true,
    });
  });
});
